    'support.faq.b2.q': 'How do I pay?',
    'support.faq.b2.a': 'Top up your AI Markets wallet, then checkout from the cart. Balance is deducted when payment succeeds.',
    'support.faq.b3.q': 'Can I get a refund?',
    'support.faq.b3.a': 'For digital services you can open a dispute within 48 hours if the product does not match the listing.',
