    'train.guide.video.1': '全身入镜，机位固定，背景简洁，光线充足。快速动作建议以 60 fps 拍摄。',
    'train.guide.video.2': '动作识别：每段视频只含一个动作，并标注正确名称。至少需要 2 个标签；每个标签建议 5–10 段视频。',
